#include "er/runtime.h"
#include <stdio.h>
#define CHECK(x) do { if (!(x)) { fprintf(stderr, "FAIL:%d: %s\n", __LINE__, #x); return 1; } } while (0)
int main(void){er_runtime_t r;er_limits_t l={{-3,-3},{3,3},{2,2}};er_runtime_init(&r,&l);CHECK(er_runtime_arm(&r)==ER_OK);er_command_t c={1000,1,{1,1},{1,1}};CHECK(er_runtime_submit_command(&r,&c)==ER_OK);er_sensor_t s={1000,{0,0},{0,0},true};er_output_t o;CHECK(er_runtime_step(&r,1000,&s,&o)==ER_OK&&o.enabled);CHECK(er_runtime_step(&r,101001,&s,&o)==ER_EFAULT);CHECK(er_runtime_faults(&r)!=0);CHECK(er_runtime_reset_faults(&r)==ER_OK);c.sequence=2;c.timestamp_us=102000;CHECK(er_runtime_submit_command(&r,&c)==ER_OK);CHECK(er_runtime_arm(&r)==ER_OK);s.valid=false;CHECK(er_runtime_step(&r,102000,&s,&o)==ER_EFAULT);printf("runtime tests passed\n");return 0;}
